// Published fixture documents are the source of truth for the simulated extraction.
const packets=new Map();let activeEvidence=null,rateDraft='',certificate=null,packetError='';
const basePacketPanel=packetPanel,baseWorkflowField=workflowField,baseV3Bind=bind,baseV3Profile=profile,baseV3Import=importScreen;
async function loadPacket(type=state.type){if(packets.has(type))return packets.get(type);const response=await fetch(`samples/${type.toLowerCase()}/packet.json`);if(!response.ok)throw Error('Sample source packet could not be loaded.');const packet=await response.json();for(const [key,field]of Object.entries(packet.fields)){const doc=packet.documents[field.doc];if(!doc||field.start<0||field.end>doc.text.length||field.end<=field.start)throw Error('Invalid source citation: '+key);if(field.kind==='direct'&&!doc.text.slice(field.start,field.end).includes(field.value))throw Error('Citation does not support '+key)}packets.set(type,packet);return packet}
function currentPacket(){return packets.get(state.type)}
function docPath(doc){return `samples/${state.type.toLowerCase()}/${doc.filename}`}
function highlightedText(text,field){if(!field)return esc(text);return esc(text.slice(0,field.start))+`<mark id="evidence-passage">${esc(text.slice(field.start,field.end))}</mark>`+esc(text.slice(field.end))}
importScreen=function(){const p=currentPacket();const library=p?`<details class="sample-library"><summary>Explore the sample email, call transcript & attachments</summary><p>These are the actual fictional files behind the sample draft.</p>${Object.entries(p.documents).map(([id,doc])=>`<div class="sample-library-row"><button class="text-btn" data-open-doc="${id}">${esc(doc.title)} ↗</button><a href="${docPath(doc)}" download>Download</a></div>`).join('')}${state.tab==='transcript'?'<button class="secondary" id="load-sample-transcript">Load sample call transcript →</button>':''}</details>`:'';return baseV3Import().replace('<div class="footer">',library+'<div class="footer">')};
packetPanel=function(){const p=currentPacket();if(!p)return `<section class="card source-panel"><span class="eyebrow">SAMPLE SOURCE LIBRARY</span><h2 style="margin-top:15px">${packetError?'Source library unavailable':'Opening the source packet…'}</h2><p>${esc(packetError||'Loading the actual sample documents used for this vendor.')}</p><button class="secondary" id="retry-packet">Retry source library</button></section>`;const doc=p.documents[sourceTab]||p.documents.call;const field=activeEvidence&&p.fields[activeEvidence]?.doc===doc.id?p.fields[activeEvidence]:null;return `<section class="card source-panel"><span class="eyebrow">THE SOURCE LIBRARY · ${esc(p.vendor)}</span><h2 style="margin-top:12px">Every detail has a paper trail.</h2><p style="font-size:12px">These are fictional, downloadable documents. The simulated draft reads this same packet; editing a field never rewrites its source.</p><div class="source-tabs">${Object.entries(p.documents).map(([id,d])=>`<button data-source-tab="${id}" class="${sourceTab===id?'selected':''}">${esc(sourceNames[id])}</button>`).join('')}</div><div class="document-bar"><span>${esc(doc.filename)}</span><a href="${docPath(doc)}" download>Download source ↓</a></div>${field?`<div class="citation-label">Highlighted: ${esc(labels[activeEvidence])}</div>`:''}<pre class="source-document">${highlightedText(doc.text,field)}</pre><div class="notice">${state.mode==='before'?'Read and organize the same documents AI uses. Copy and paste is welcome.':'Exact passages are linked to each draft field. Extraction is simulated; source evidence is inspectable.'}</div></section>`};
showSource=function(key){const p=currentPacket();if(!p){toast('Source packet is still loading. Try again shortly.');return}if(key==='insurance'&&certificate){showCertificate();return}const f=p.fields[key];if(!f){toast('No source passage exists for this field.');return}activeEvidence=key;sourceTab=f.doc;const doc=p.documents[f.doc],value=state.step>1?(state.data[key]??f.value):f.value,manual=value!==f.value;$('#source-title').textContent=`${labels[key]} · ${sourceNames[f.doc]}`;$('#source-copy').innerHTML=`<div class="citation-label">${manual?'Rep-edited value · source retained below':'Exact passage from '+esc(doc.filename)}</div><div class="current-value"><small>CURRENT RECORD VALUE</small><strong>${esc(value)}</strong>${manual?'<p>This value was edited by the rep. It is not presented as a source quote.</p>':''}</div><div class="document-bar"><span>Sample source · full document</span><a href="${docPath(doc)}" download>Download original ↓</a></div><pre class="evidence-document">${highlightedText(doc.text,f)}</pre>${f.kind!=='direct'?`<div class="notice">${f.kind==='missing-document'?'The email says the certificate is not attached; the pending status is inferred from that absence.':f.kind==='follow-up-draft'?'This task is a drafted follow-up based on the missing attachment, rather than a quote.':'This is a vendor statement, not independent verification.'}</div>`:''}`;$('#source').showModal();requestAnimationFrame(()=>$('#source-copy mark')?.scrollIntoView({block:'center'}))};
workflowField=function(k,auto){let html=baseWorkflowField(k,auto);if(auto&&k==='insurance'&&certificate)html=html.replace('⚑ Missing documentation','Attachment received · review status below').replace(sourceNames[origin[k]],'Uploaded certificate');if(auto&&currentPacket()){const f=currentPacket().fields[k];if(f&&state.data[k]!==f.value&&!(k==='insurance'&&certificate))html=html.replace('Source-backed draft','Rep edited · source retained');}return html};
function certificateCard(){return `<div class="decision certificate-card ${decisions.insurance?'resolved':''}"><span class="eyebrow">03 · SUPPORTING DOCUMENTS</span><h3 style="margin-top:12px">${certificate?'Certificate received. Review the details.':'Bring the insurance certificate into the record.'}</h3><p>Attach a PDF, PNG, or JPG. Files stay in this browser session. Receipt and review are separate from coverage verification.</p><div class="attachment-actions"><a class="secondary" href="samples/golden-hour-sample-certificate.pdf" download>Download sample PDF ↓</a><button class="secondary" id="choose-certificate">${certificate?'Replace attachment':'Upload certificate ↑'}</button><input id="certificate-upload" type="file" accept="application/pdf,image/png,image/jpeg" hidden></div><small class="sample-caption">Sample PDF: Golden Hour Photography · fictional coverage for Jan–Dec 2027.</small>${certificate?`<div class="attachment-file"><span>▤ &nbsp; ${esc(certificate.name)}</span><button class="text-btn" id="preview-certificate">Preview attachment ↗</button></div><p class="sample-caption">${certificate.recognized?'Recognized demo PDF by file checksum. The details below match the generated sample.':'Document received. This demo does not extract arbitrary PDFs or images; enter the details from the attachment.'}</p><div class="fields"><div class="field full"><label for="cert-name">Insured business name</label><input id="cert-name" value="${esc(certificate.insured||'')}" data-cert="insured"></div><div class="field full"><label for="cert-limit">Liability limits</label><input id="cert-limit" value="${esc(certificate.limit||'')}" data-cert="limit" placeholder="e.g. $1,000,000 per occurrence"></div><div class="field"><label for="cert-start">Coverage begins</label><input type="date" id="cert-start" value="${esc(certificate.start||'')}" data-cert="start"></div><div class="field"><label for="cert-expiry">Coverage expires</label><input type="date" id="cert-expiry" value="${esc(certificate.expiry||'')}" data-cert="expiry"></div></div><div class="notice">${certificate.recognized?'This sample is clearly marked NOT VALID. It demonstrates document handling, not real insurance.':'Check the insured name, limits, dates, and authenticity against your onboarding requirements.'}</div><button class="primary" id="review-certificate" style="margin-top:15px">${certificate.reviewed?'✓ Document details reviewed':'Record document review'}</button>`:`<button class="text-btn" id="keep-pending">${decisions.insurance?'✓ Kept pending; follow-up draft prepared':'Continue with certificate pending →'}</button>`}</div>`}
decisionCards=function(){const p=currentPacket(),current=state.data.price||p?.fields.price.value||'';if(!rateDraft)rateDraft=current;return `<div class="decision ${decisions.price?'resolved':''}"><span class="eyebrow">01 · PRICING DECISION</span><h3 style="margin-top:12px">Set the current starting rate.</h3><div class="rate-comparison"><div><small>OLD WEBSITE</small><strong>${esc(p?.oldPrice||'Prior season')}</strong></div><div><small>FOLLOW-UP EMAIL</small><strong>${esc(p?.fields.price.value||samples[state.type].price)}</strong></div><div><small>CURRENT RECORD</small><strong>${esc(current)}</strong></div></div><p>Use the emailed rate, or enter a rate you have confirmed with the vendor.</p><label for="current-rate">Current starting rate</label><div class="rate-input"><input id="current-rate" value="${esc(rateDraft)}" placeholder="e.g. $4,500 or $85 per guest"><button class="primary" id="confirm-rate">${decisions.price?'✓ Confirmed':'Confirm rate'}</button></div><div class="rate-options"><button class="text-btn" id="use-source-rate">Use email: ${esc(p?.fields.price.value||samples[state.type].price)}</button><button class="text-btn" data-evidence="price">Read the original email ↗</button></div><p id="rate-status">${decisions.price?'Confirmed current rate: '+esc(current)+(state.data.rateProvenance==='rep'?' · Rep-entered override.':' · Matches the vendor email.'):'Waiting for your rate confirmation.'}</p></div><div class="decision ${decisions.delivery?'resolved':''}"><span class="eyebrow">02 · DELIVERY / PLANNING</span><h3 style="margin-top:12px">Resolve the timeline.</h3><p>The follow-up email confirms: <b>${esc(p?.fields.delivery.value||samples[state.type].delivery)}</b></p><button class="secondary" data-decision="delivery">${decisions.delivery?'✓ Email timeline confirmed':'Use the confirmed email timeline'}</button><button class="text-btn" data-evidence="delivery">Read the original email ↗</button></div>${certificateCard()}${decisions.insurance&&!certificate?.reviewed?`<label for="followup-draft">Follow-up draft · nothing is sent</label><textarea id="followup-draft" class="followup">Hi ${esc(samples[state.type].contact)},\n\nThanks for the updates. Please send your current liability insurance certificate showing the insured name, limits, coverage period, and expiry, plus supporting license documentation where applicable.\n\nJamie · I Do! vendor success</textarea><button class="text-btn" id="copy-followup">Copy draft</button>`:''}`};
async function receiveCertificate(file){if(!file)return;const allowed=['application/pdf','image/png','image/jpeg'];if(!allowed.includes(file.type)||file.size>10*1024*1024){toast('Choose a PDF, PNG, or JPG under 10 MB.');return}try{const bytes=await file.arrayBuffer();const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(n=>n.toString(16).padStart(2,'0')).join('');const metaResponse=await fetch('samples/certificate-meta.json');if(!metaResponse.ok)throw Error('Sample metadata unavailable');const meta=await metaResponse.json(),recognized=digest===meta.sha256;if(certificate?.url)URL.revokeObjectURL(certificate.url);certificate={name:file.name,url:URL.createObjectURL(file),mime:file.type,bytes:file.size,recognized,reviewed:false,insured:recognized?meta.name:'',limit:recognized?meta.limit:'',start:recognized?meta.start:'',expiry:recognized?meta.expiry:'',policy:recognized?meta.policy:''};decisions.insurance=false;reviewed.delete(5);const target=state.mode==='before'?state.manual:state.data;target.insurance=`Received: ${file.name} — awaiting document review`;render();toast('Certificate attached. Review its details below.')}catch{toast('Could not read the attachment. Please try again.')}}
function showCertificate(){if(!certificate)return;$('#source-title').textContent='Uploaded insurance certificate';$('#source-copy').innerHTML=`<div class="document-bar"><span>${esc(certificate.name)}</span><a href="${certificate.url}" download="${esc(certificate.name)}">Download attachment ↓</a></div>${certificate.mime==='application/pdf'?`<iframe class="certificate-preview" title="Uploaded insurance certificate" src="${certificate.url}"></iframe>`:`<img class="certificate-image" alt="Uploaded insurance certificate" src="${certificate.url}">`}<p class="sample-caption">${certificate.recognized?'Fictional sample. Not valid insurance.':'User-supplied attachment. Authenticity and coverage are not verified.'}</p>`;$('#source').showModal()}
const v3Review=reviewScreen;reviewScreen=function(){return v3Review().replace('This record will remain pending documentation.','Document receipt and review will be recorded. License documentation may still be outstanding.')};
const v3Manual=manualScreen;manualScreen=function(){let html=v3Manual();if(sectionIndex===5)html=html.replace('<div class="fields">',certificateCard()+'<div class="fields">');return html};
profile=function(){let html=baseV3Profile();if(state.data.insuranceAttachment?.reviewed)html=html.replace('insurance and license documents still require vendor follow-up.','insurance attachment received and reviewed; license documentation still requires follow-up.');return html};
bind=function(){baseV3Bind();document.querySelectorAll('[data-source-tab]').forEach(b=>b.onclick=()=>{sourceTab=b.dataset.sourceTab;activeEvidence=null;render()});document.querySelectorAll('[data-open-doc]').forEach(b=>b.onclick=()=>{const key=({website:'name',call:'services',rates:'price2',portfolio:'headline',email:'price'})[b.dataset.openDoc];showSource(key)});if($('#load-sample-transcript'))$('#load-sample-transcript').onclick=()=>{state.transcript=currentPacket().documents.call.text;render();toast('Sample call transcript added.')} ;if($('#retry-packet'))$('#retry-packet').onclick=()=>loadPacket().then(()=>{packetError='';render()}).catch(e=>{packetError=e.message;render()});if($('#extract'))$('#extract').onclick=async()=>{if(state.tab==='transcript'?!state.transcript.trim():!/^https?:\/\/\S+\.\S+/.test(state.url)){toast(state.tab==='transcript'?'Paste or upload a transcript to continue.':'Add a URL or use the sample vendor.');return}try{const p=await loadPacket();state.data=Object.fromEntries(Object.entries(p.fields).map(([k,f])=>[k,f.value]));state.data.sourcePacket=`samples/${state.type.toLowerCase()}/packet.json`;sectionIndex=0;aiStarted=null;rateDraft=state.data.price;if(certificate?.url)URL.revokeObjectURL(certificate.url);certificate=null;activeEvidence=null;state.step=2;render();window.scrollTo(0,0);toast('Sample packet mapped to 46 draft fields. Sources are linked.')}catch(e){toast(e.message)}};
if($('#type')){const previous=$('#type').onchange;$('#type').onchange=async e=>{previous(e);rateDraft='';certificate=null;try{await loadPacket();render()}catch(error){packetError=error.message;render()}}}if($('#work-type')){const previous=$('#work-type').onchange;$('#work-type').onchange=async e=>{previous(e);certificate=null;try{await loadPacket();render()}catch(error){packetError=error.message;render()}}}
if($('#current-rate'))$('#current-rate').oninput=e=>{rateDraft=e.target.value;decisions.price=false;reviewed.delete(5);$('#rate-status').textContent='Unsaved rate: '+rateDraft;$('#confirm-rate').textContent='Confirm rate';if($('#finish-ai'))$('#finish-ai').disabled=true};if($('#use-source-rate'))$('#use-source-rate').onclick=()=>{rateDraft=currentPacket().fields.price.value;decisions.price=false;render()};if($('#confirm-rate'))$('#confirm-rate').onclick=()=>{const value=rateDraft.trim();if(!value||!/[0-9]/.test(value)||value.length>100){toast('Enter a starting rate, including the amount and any unit.');return}const changed=state.data.price!==value;state.data.price=value;state.data.rateProvenance=value===currentPacket().fields.price.value?'vendor-email':'rep';decisions.price=true;reviewed.delete(5);if(changed)reviewed.delete(2);render();toast('Current starting rate confirmed: '+value)};
const priceField=$('[data-work-key="price"]');if(priceField){const previous=priceField.oninput;priceField.oninput=e=>{previous(e);rateDraft=e.target.value;decisions.price=false;reviewed.delete(5)}}
if($('#choose-certificate'))$('#choose-certificate').onclick=()=>$('#certificate-upload').click();if($('#certificate-upload'))$('#certificate-upload').onchange=e=>receiveCertificate(e.target.files[0]);document.querySelectorAll('[data-cert]').forEach(input=>input.oninput=e=>{certificate[e.target.dataset.cert]=e.target.value;certificate.reviewed=false;decisions.insurance=false;reviewed.delete(5);if($('#finish-ai'))$('#finish-ai').disabled=true;if($('#review-certificate'))$('#review-certificate').textContent='Record document review'});if($('#preview-certificate'))$('#preview-certificate').onclick=showCertificate;if($('#keep-pending'))$('#keep-pending').onclick=()=>{decisions.insurance=true;reviewed.delete(5);(state.mode==='before'?state.manual:state.data).insurance='Pending — insurance certificate requested';render()};if($('#review-certificate'))$('#review-certificate').onclick=()=>{const c=certificate,target=state.mode==='before'?state.manual:state.data;if(!c.insured.trim()||!c.limit.trim()||!c.start||!c.expiry){toast('Enter the insured business, liability limits, and coverage dates.');return}if(c.start>=c.expiry){toast('Coverage expiry must follow the coverage start date.');return}const vendor=target.name||samples[state.type].name;if(c.insured.trim().toLowerCase()!==vendor.trim().toLowerCase()){toast('The insured business does not match this vendor. Check the attachment.');return}c.reviewed=true;decisions.insurance=true;reviewed.delete(5);target.insurance=`${c.recognized?'Fictional sample':'Document'} received and reviewed: ${c.name}; insured ${c.insured}; ${c.limit}; ${c.start} to ${c.expiry}. Coverage not independently verified.`;target.insuranceAttachment={filename:c.name,insured:c.insured,limit:c.limit,start:c.start,expiry:c.expiry,reviewed:true,sample:c.recognized};target.followup='Request supporting license documentation; independently verify insurance coverage before final clearance.';render();toast('Document review recorded. Coverage remains unverified.')};
const save=$('#finish-ai');if(save){const original=save.onclick;save.onclick=()=>{if(certificate)state.data.insuranceAttachment={filename:certificate.name,insured:certificate.insured,limit:certificate.limit,start:certificate.start,expiry:certificate.expiry,reviewed:certificate.reviewed,sample:certificate.recognized};original()}};
};
loadPacket().then(()=>render()).catch(e=>{packetError=e.message;render()});


